-- achievements (6 rows)

-- events (3 rows)
-- Re-sync auto-increment sequences after loading rows with explicit IDs
-- (without this, the next INSERT without an explicit id collides with
-- an id that already exists, since Postgres's sequence counter doesn't
-- know these rows were inserted)
SELECT setval(pg_get_serial_sequence('cadets','id'),        COALESCE((SELECT MAX(id) FROM cadets),1));
SELECT setval(pg_get_serial_sequence('rank_holders','id'),  COALESCE((SELECT MAX(id) FROM rank_holders),1));
SELECT setval(pg_get_serial_sequence('alumni','id'),        COALESCE((SELECT MAX(id) FROM alumni),1));
SELECT setval(pg_get_serial_sequence('achievements','id'),  COALESCE((SELECT MAX(id) FROM achievements),1));
SELECT setval(pg_get_serial_sequence('events','id'),        COALESCE((SELECT MAX(id) FROM events),1));
SELECT setval(pg_get_serial_sequence('gallery','id'),       COALESCE((SELECT MAX(id) FROM gallery),1));
